#!/usr/bin/env php
<?php

declare(strict_types=1);

/**
 * Regenerates src/Types/*.php: one PHP class per concrete Telegram Bot API
 * object type (InlineKeyboardMarkup, ReplyParameters, ChatPermissions, ...)
 * and one marker interface per abstract type (InputMedia, ChatMember, ...),
 * so these objects can be constructed and passed directly into the typed
 * methods generated by tools/generate-methods.php instead of hand-built
 * associative arrays.
 *
 * Every generated class is an immutable, promoted-constructor value object
 * implementing \JsonSerializable (required fields as required positional
 * parameters, optional fields as nullable named parameters), so passing one
 * to TelegramClient::call()/a generated method "just works": json_encode()
 * calls jsonSerialize() automatically, including recursively for nested
 * Types objects.
 *
 * "InputFile" is intentionally skipped: that concept is already represented
 * by Bazzastyle\BazzaBot\Http\InputFile (a local-file upload wrapper).
 *
 * Source of truth: the community-maintained machine-readable spec at
 * https://github.com/davtur19/TuriBotGen (see tools/lib/spec-support.php).
 *
 * Run this whenever Telegram publishes a new Bot API version (together
 * with generate-methods.php — see tools/generate-api.php to run both):
 *
 *   php tools/generate-types.php
 *
 * It fully replaces every AUTO-GENERATED file under src/Types/ — review the
 * diff and run the test suite before committing.
 */

require __DIR__ . '/lib/spec-support.php';

const OUTPUT_DIR = __DIR__ . '/../src/Types';

/**
 * @param array<string, true> $abstractNames
 * @param array<string, true> $knownTypeNames
 * @param array<string, array<int, string>> $implementsMap
 */
function generateClass(stdClass $type, array $abstractNames, array $knownTypeNames, array $implementsMap): string
{
    $required = [];
    $optional = [];
    foreach ($type->fields ?? [] as $field) {
        if ($field->optional) {
            $optional[] = $field;
        } else {
            $required[] = $field;
        }
    }

    $ctorLines = [];
    $docParamLines = [];
    $serializeLines = [];

    foreach ($required as $field) {
        $fieldType = nullableType(mapFieldType($field->types, $abstractNames, $knownTypeNames), false);
        $ctorLines[] = "public readonly {$fieldType} \${$field->name},";
        $docParamLines[] = " * @param {$fieldType} \${$field->name} " . wrapComment($field->description, ' *     ');
        $serializeLines[] = "        \$data['{$field->name}'] = \$this->{$field->name};";
    }

    foreach ($optional as $field) {
        $fieldType = nullableType(mapFieldType($field->types, $abstractNames, $knownTypeNames), true);
        $ctorLines[] = "public readonly {$fieldType} \${$field->name} = null,";
        $docParamLines[] = " * @param {$fieldType} \${$field->name} " . wrapComment($field->description, ' *     ') . ' (optional)';
        $serializeLines[] = "        if (\$this->{$field->name} !== null) \$data['{$field->name}'] = \$this->{$field->name};\n";
    }

    $interfaces = $implementsMap[$type->name] ?? [];
    $implementsList = implode(', ', array_merge($interfaces, ['\\JsonSerializable']));

    $constructorBlock = $ctorLines === []
        ? ''
        : "    public function __construct(\n        " . implode("\n        ", $ctorLines) . "\n    ) {\n    }\n\n";

    $serializeBody = $serializeLines === []
        ? '        return [];'
        : "        \$data = [];\n" . implode("\n", $serializeLines) . "\n\n        return \$data;";

    $classDoc = array_merge(
        [' * ' . wrapComment($type->description, ' * ')],
        [' *'],
        [' * @see https://core.telegram.org/bots/api#' . strtolower($type->name)],
        $docParamLines === [] ? [] : array_merge([' *'], $docParamLines),
    );

    return "<?php\n\ndeclare(strict_types=1);\n\nnamespace Bazzastyle\\BazzaBot\\Types;\n\n"
        . "/**\n * AUTO-GENERATED — DO NOT EDIT BY HAND. Regenerate with: php tools/generate-types.php\n *\n"
        . implode("\n", $classDoc) . "\n */\n"
        . "final class {$type->name} implements {$implementsList}\n{\n"
        . $constructorBlock
        . "    /**\n     * @return array<string, mixed>\n     */\n"
        . "    public function jsonSerialize(): array\n    {\n{$serializeBody}\n    }\n"
        . "}\n";
}

$spec = fetchSpec();
$abstractNames = abstractTypeNames($spec);
$knownTypeNames = knownTypeNames($spec);

/** @var array<string, array<int, string>> $implementsMap concrete type name -> interface names */
$implementsMap = [];
foreach ($spec->types as $type) {
    if (isset($abstractNames[$type->name])) {
        foreach ($type->extended_by as $concreteName) {
            $implementsMap[$concreteName][] = $type->name;
        }
    }
}

clearGeneratedFiles(OUTPUT_DIR);

$interfaceCount = 0;
$classCount = 0;

foreach ($spec->types as $type) {
    if ($type->name === 'InputFile') {
        continue; // represented by Bazzastyle\BazzaBot\Http\InputFile instead
    }

    if (isset($abstractNames[$type->name])) {
        $body = "<?php\n\ndeclare(strict_types=1);\n\nnamespace Bazzastyle\\BazzaBot\\Types;\n\n"
            . "/**\n * AUTO-GENERATED — DO NOT EDIT BY HAND. Regenerate with: php tools/generate-types.php\n *\n"
            . ' * ' . wrapComment($type->description, ' * ') . "\n"
            . (($type->extended_by ?? []) === [] ? '' : " *\n * Implemented by: " . implode(', ', $type->extended_by) . ".\n")
            . " *\n * @see https://core.telegram.org/bots/api#" . strtolower($type->name) . "\n */\n"
            . "interface {$type->name} extends \\JsonSerializable\n{\n}\n";

        file_put_contents(OUTPUT_DIR . "/{$type->name}.php", $body);
        $interfaceCount++;

        continue;
    }

    file_put_contents(
        OUTPUT_DIR . "/{$type->name}.php",
        generateClass($type, $abstractNames, $knownTypeNames, $implementsMap),
    );
    $classCount++;
}

fwrite(STDOUT, sprintf(
    "Generated %d classes + %d interfaces from Telegram Bot API spec v%s -> %s\n",
    $classCount,
    $interfaceCount,
    $spec->version,
    OUTPUT_DIR,
));
